; ea_gfx_02_bss_01 1CF29C-1CF54C  NHL 97 PC HOCKEY.EXE dseg04
; Zero-filled polygon fill and text origin variables.
; generated by tools/build/gen_src.py, assembled by ./build.sh (see docs/ASM_BUILD.md)
bits 32
%include "hockey.inc"
section s_1CF29C nobits alloc noexec write align=1
global PolyTopRow, PolyRowCount, FillColor, TextOriginX, TextOriginY, FontAscent, FontDescent, TextAlign
global CurrentFont, FontHeight, FontWidth, LinkTextFont, PolySpanEdges
PolyTopRow:                                     ; top row of the polygon being filled; used by FillPolySpans,
                                                ; FillPolygon
        resb 4
PolyRowCount:                                   ; number of rows of the polygon being filled; used by
                                                ; FillPolygon
        resb 4
PolySpanEdges:                                  ; left and right edge of each row of the polygon being filled;
                                                ; used by FillPolySpans, FillPolygon
        resb 640
FillColor:                                      ; colour used by the rectangle and row fillers
        resb 4
TextOriginX:                                    ; x of the text drawing position; used by DebugPrintAt,
                                                ; DebugPrintf, DrawTextLimited ...
        resb 4
TextOriginY:                                    ; y of the text drawing position; used by DebugPrintAt,
                                                ; DebugPrintf, DrawTextLimited ...
        resb 4
FontAscent:                                     ; height of the current font above the baseline; used by
                                                ; DrawTextRun, SelectFont
        resb 4
FontDescent:                                    ; depth of the current font below the baseline; used by
                                                ; DrawTextRun, SelectFont
        resb 4
TextAlign:                                      ; alignment of drawn text; used by DrawTextAligned,
                                                ; PrepareTextDraw, RefreshTextColors ...
        resb 4
CurrentFont:                                    ; pointer to the current font; used by PrepareTextDraw,
                                                ; RefreshTextColors, SelectFont ...
        resb 4
FontHeight:                                     ; line height of the current font; used by DrawTextRun,
                                                ; SelectFont
        resb 4
FontWidth:                                      ; widest glyph of the current font; used by DrawTextRun,
                                                ; SelectFont
        resb 4
LinkTextFont:                                   ; font used on the link game screens; used by
                                                ; ChooseNetworkGameScreen, DrawLinesIntroText, DrawLinkBox ...
        resb 4
